// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        // owner is initially address(0); only address(0) passes onlyOwner
        vm.prank(address(0));
        try c.transferOwnership(newOwner) {
            // Rule: after a successful transferOwnership by the owner, owner() == newOwner
            assertTrue(c.owner() == newOwner);
        } catch {
            assertTrue(true);
        }
    }
}
